import fs from 'node:fs';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { gunzipSync } from 'node:zlib';
import { fileURLToPath } from 'node:url';

export const HUNDRED_HAND_RUNTIME_ASSET = Object.freeze({
  input: 'scripts/assets/hundred-hand-mile/render.glb.gz',
  output: 'assets/ships/release/render-packages/hundred-hand-mile/render.glb',
  compressedBytes: 421855,
  compressedSha256: 'c50e3b448ad444501d4ccb9a19d4da31f4dae88c4c00fcbb8c000288abfbf5fa',
  bytes: 855976,
  sha256: 'dc23f5073fc3039c247a0ae317aa319cc7b9e97d12f648da61c58a2e2b9d4c63',
});
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
function contained(root, relative) {
  if (typeof relative !== 'string' || !relative || relative.includes('\\') ||
      relative.includes('\0') || /^[a-zA-Z][a-zA-Z\d+.-]*:/.test(relative) ||
      relative.split('/').some(part => !part || part === '.' || part === '..'))
    throw new Error('unsafe asset path');
  const target = path.resolve(root, relative);
  if (!target.startsWith(root + path.sep)) throw new Error('asset path escapes root');
  return target;
}
function assertComponents(target, allowMissing = false) {
  const parsed = path.parse(target);
  let current = parsed.root;
  const parts = target.slice(parsed.root.length).split(path.sep).filter(Boolean);
  for (let i = 0; i < parts.length; i++) {
    current = path.join(current, parts[i]);
    const entry = fs.lstatSync(current, { throwIfNoEntry: false });
    if (!entry) {
      if (allowMissing) return;
      throw new Error('missing asset path: ' + current);
    }
    if (entry.isSymbolicLink()) throw new Error('asset symlink refused: ' + current);
    if (i < parts.length - 1 && !entry.isDirectory()) throw new Error('asset parent is not a directory');
  }
}
function readPinned(filename, bytes, digest) {
  assertComponents(filename);
  if (!fs.lstatSync(filename).isFile()) throw new Error('asset is not a regular file: ' + filename);
  const fd = fs.openSync(filename, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW || 0));
  try {
    const entry = fs.fstatSync(fd);
    if (!entry.isFile() || entry.size !== bytes) throw new Error('asset byte count mismatch: ' + filename);
    const buffer = Buffer.alloc(bytes + 1);
    let count = 0;
    while (count < buffer.length) {
      const n = fs.readSync(fd, buffer, count, buffer.length - count, null);
      if (!n) break;
      count += n;
    }
    if (count !== bytes || sha256(buffer.subarray(0, count)) !== digest)
      throw new Error('asset checksum mismatch: ' + filename);
    return buffer.subarray(0, count);
  } finally { fs.closeSync(fd); }
}
function ensureParents(root, directory) {
  let current = root;
  for (const part of path.relative(root, directory).split(path.sep).filter(Boolean)) {
    current = path.join(current, part);
    assertComponents(current, true);
    try { fs.mkdirSync(current); }
    catch (error) { if (error.code !== 'EEXIST') throw error; }
    assertComponents(current);
    if (!fs.lstatSync(current).isDirectory()) throw new Error('asset parent is not a directory');
  }
}
// Explicit preparation only. No import-time writes, network, fallback or model regeneration.
// Existing bytes are authoritative: a mismatch is an error, never permission to overwrite.
export function materializePinnedGzip(root, spec) {
  root = path.resolve(root);
  assertComponents(root);
  if (!fs.lstatSync(root).isDirectory()) throw new Error('asset root is not a directory');
  for (const key of ['compressedBytes', 'bytes'])
    if (!Number.isSafeInteger(spec[key]) || spec[key] < 1 || spec[key] > 16 * 1024 * 1024)
      throw new Error('invalid bounded asset size');
  for (const key of ['compressedSha256', 'sha256'])
    if (!/^[a-f0-9]{64}$/.test(spec[key])) throw new Error('invalid asset checksum');
  const input = contained(root, spec.input), output = contained(root, spec.output);
  if (input === output) throw new Error('asset input and output must differ');
  const compressed = readPinned(input, spec.compressedBytes, spec.compressedSha256);
  assertComponents(output, true);
  if (fs.lstatSync(output, { throwIfNoEntry: false })) {
    readPinned(output, spec.bytes, spec.sha256);
    return { created: false, path: output, bytes: spec.bytes, sha256: spec.sha256 };
  }
  const raw = gunzipSync(compressed, { maxOutputLength: spec.bytes });
  if (raw.length !== spec.bytes || sha256(raw) !== spec.sha256)
    throw new Error('expanded asset identity mismatch');
  ensureParents(root, path.dirname(output));
  const temporary = path.join(path.dirname(output), '.hundred-hand-' + randomUUID() + '.tmp');
  let owned = null;
  let created = false;
  try {
    const fd = fs.openSync(temporary, 'wx', 0o644);
    try {
      owned = fs.fstatSync(fd);
      fs.writeFileSync(fd, raw);
      fs.fsyncSync(fd);
    } finally { fs.closeSync(fd); }
    assertComponents(output, true);
    // Same-directory link publishes a complete file and never replaces an existing destination.
    // No rename fallback: filesystems without hard-link support fail closed.
    try { fs.linkSync(temporary, output); created = true; }
    catch (error) { if (error.code !== 'EEXIST') throw error; }
    readPinned(output, spec.bytes, spec.sha256);
    return { created, path: output, bytes: spec.bytes, sha256: spec.sha256 };
  } finally {
    if (owned) {
      const current = fs.lstatSync(temporary, { throwIfNoEntry: false });
      if (current && current.isFile() && current.dev === owned.dev && current.ino === owned.ino)
        fs.unlinkSync(temporary);
    }
  }
}
export function materializeHundredHandRuntimeAsset(root) {
  return materializePinnedGzip(root, HUNDRED_HAND_RUNTIME_ASSET);
}

if (import.meta.url.startsWith('file:') && process.argv[1] &&
    path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const result = materializeHundredHandRuntimeAsset(fileURLToPath(new URL('../../', import.meta.url)));
  console.log(JSON.stringify(result));
}

