import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createHash } from 'node:crypto';
import { gzipSync } from 'node:zlib';
import { materializePinnedGzip } from '../scripts/lib/materializeHundredHandRuntimeAsset.mjs';

const TEMP_ROOT = fs.realpathSync(os.tmpdir());
const hash = value => createHash('sha256').update(value).digest('hex');
const raw = Buffer.from('original model bytes\n'.repeat(16));
const compressed = gzipSync(raw);
const baseSpec = { input: 'input.gz', output: 'assets/render.glb',
  compressedBytes: compressed.length, compressedSha256: hash(compressed),
  bytes: raw.length, sha256: hash(raw) };
function reserve() {
  const info = fs.statfsSync(TEMP_ROOT);
  assert(info.bavail * info.bsize >= 3072 * 1024, 'retain at least 3072 KiB temporary reserve');
}
async function fixture(run) {
  reserve();
  const root = fs.mkdtempSync(path.join(TEMP_ROOT, 'hh-materialize-test-'));
  try {
    fs.writeFileSync(path.join(root, 'input.gz'), compressed);
    await run(root, { ...baseSpec });
  } finally {
    // This root was exclusively created above; never remove any supplied or pre-existing root.
    fs.rmSync(root, { recursive: true, force: true });
    reserve();
  }
}
const output = root => path.join(root, baseSpec.output);
const noTemps = root => {
  if (fs.existsSync(path.join(root, 'assets')))
    assert.equal(fs.readdirSync(path.join(root, 'assets')).filter(x => x.endsWith('.tmp')).length, 0);
};
test('bounded gzip asset preparation preserves exact bytes and foreign state', async t => {
  await t.test('baseline absent output becomes exact ordinary file, repeat keeps mtime', () => fixture(root => {
    assert.equal(fs.existsSync(output(root)), false);
    assert.equal(materializePinnedGzip(root, baseSpec).created, true);
    assert.deepEqual(fs.readFileSync(output(root)), raw);
    const before = fs.statSync(output(root), { bigint: true });
    assert.equal(materializePinnedGzip(root, baseSpec).created, false);
    assert.equal(fs.statSync(output(root), { bigint: true }).mtimeNs, before.mtimeNs);
    noTemps(root);
  }));
  await t.test('missing compressed input fails without output', () => fixture(root => {
    fs.unlinkSync(path.join(root, 'input.gz'));
    assert.throws(() => materializePinnedGzip(root, baseSpec), /missing/);
    assert.equal(fs.existsSync(output(root)), false);
  }));
  await t.test('wrong compressed checksum fails even with valid cached output', () => fixture(root => {
    materializePinnedGzip(root, baseSpec);
    assert.throws(() => materializePinnedGzip(root, { ...baseSpec, compressedSha256: '0'.repeat(64) }), /checksum/);
    assert.deepEqual(fs.readFileSync(output(root)), raw);
  }));
  await t.test('compressed byte count is pinned', () => fixture(root => {
    assert.throws(() => materializePinnedGzip(root, { ...baseSpec, compressedBytes: compressed.length + 1 }), /byte count/);
    assert.equal(fs.existsSync(output(root)), false);
  }));
  await t.test('expanded checksum failure writes nothing', () => fixture(root => {
    assert.throws(() => materializePinnedGzip(root, { ...baseSpec, sha256: '0'.repeat(64) }), /expanded/);
    assert.equal(fs.existsSync(output(root)), false);
  }));
  await t.test('decompression is bounded and exact-length checked', () => fixture(root => {
    assert.throws(() => materializePinnedGzip(root, { ...baseSpec, bytes: raw.length - 1 }));
    assert.throws(() => materializePinnedGzip(root, { ...baseSpec, bytes: raw.length + 1 }), /expanded/);
    assert.equal(fs.existsSync(output(root)), false);
  }));
  await t.test('malformed gzip fails before output directories', () => fixture(root => {
    const bad = Buffer.from('not gzip');
    fs.writeFileSync(path.join(root, 'input.gz'), bad);
    assert.throws(() => materializePinnedGzip(root, { ...baseSpec,
      compressedBytes: bad.length, compressedSha256: hash(bad) }));
    assert.equal(fs.existsSync(path.join(root, 'assets')), false);
  }));
  await t.test('foreign mismatching output and timestamp survive', () => fixture(root => {
    fs.mkdirSync(path.join(root, 'assets'));
    const foreign = Buffer.alloc(raw.length, 120);
    fs.writeFileSync(output(root), foreign);
    const before = fs.statSync(output(root), { bigint: true });
    assert.throws(() => materializePinnedGzip(root, baseSpec), /checksum/);
    assert.deepEqual(fs.readFileSync(output(root)), foreign);
    assert.equal(fs.statSync(output(root), { bigint: true }).mtimeNs, before.mtimeNs);
    noTemps(root);
  }));
  await t.test('traversal, absolute paths, schemes and invalid sizes fail', () => fixture(root => {
    for (const input of ['../input.gz', '/input.gz', 'a//b', 'a/./b', 'a\\b', 'C:input.gz', 'a\0b'])
      assert.throws(() => materializePinnedGzip(root, { ...baseSpec, input }), /path/);
    for (const bytes of [0, -1, 1.5, Infinity, 16 * 1024 * 1024 + 1])
      assert.throws(() => materializePinnedGzip(root, { ...baseSpec, bytes }), /size/);
  }));
  await t.test('input symlink is rejected', () => fixture(root => {
    fs.renameSync(path.join(root, 'input.gz'), path.join(root, 'real.gz'));
    fs.symlinkSync('real.gz', path.join(root, 'input.gz'));
    assert.throws(() => materializePinnedGzip(root, baseSpec), /symlink/);
  }));
  await t.test('output parent symlink is rejected', () => fixture(root => {
    fs.mkdirSync(path.join(root, 'elsewhere'));
    fs.symlinkSync('elsewhere', path.join(root, 'assets'), 'dir');
    assert.throws(() => materializePinnedGzip(root, baseSpec), /symlink/);
    assert.deepEqual(fs.readdirSync(path.join(root, 'elsewhere')), []);
  }));
  await t.test('output symlink is rejected even if target bytes match', () => fixture(root => {
    fs.mkdirSync(path.join(root, 'assets'));
    fs.writeFileSync(path.join(root, 'real.glb'), raw);
    fs.symlinkSync('../real.glb', output(root));
    assert.throws(() => materializePinnedGzip(root, baseSpec), /symlink/);
  }));
  await t.test('root symlink and non-directory parent are rejected', () => fixture(root => {
    fs.symlinkSync('.', path.join(root, 'alias'), 'dir');
    assert.throws(() => materializePinnedGzip(path.join(root, 'alias'), baseSpec), /symlink/);
    fs.writeFileSync(path.join(root, 'assets'), 'foreign');
    assert.throws(() => materializePinnedGzip(root, baseSpec), /directory/);
    assert.equal(fs.readFileSync(path.join(root, 'assets'), 'utf8'), 'foreign');
  }));
  await t.test('identical concurrent winner is verified and own temporary removed', () => fixture(root => {
    const originalLink = fs.linkSync;
    fs.linkSync = (temporary, destination) => {
      fs.writeFileSync(destination, raw, { flag: 'wx' });
      return originalLink(temporary, destination);
    };
    try { assert.equal(materializePinnedGzip(root, baseSpec).created, false); }
    finally { fs.linkSync = originalLink; }
    assert.deepEqual(fs.readFileSync(output(root)), raw);
    noTemps(root);
  }));
  await t.test('foreign concurrent winner is never overwritten', () => fixture(root => {
    const originalLink = fs.linkSync;
    fs.linkSync = (temporary, destination) => {
      fs.writeFileSync(destination, 'foreign winner', { flag: 'wx' });
      return originalLink(temporary, destination);
    };
    try { assert.throws(() => materializePinnedGzip(root, baseSpec), /byte count/); }
    finally { fs.linkSync = originalLink; }
    assert.equal(fs.readFileSync(output(root), 'utf8'), 'foreign winner');
    noTemps(root);
  }));
  await t.test('publication failure cleans only own temporary and fails closed', () => fixture(root => {
    fs.mkdirSync(path.join(root, 'assets'));
    fs.writeFileSync(path.join(root, 'assets', 'foreign.tmp'), 'preserve');
    const originalLink = fs.linkSync;
    fs.linkSync = () => { const error = new Error('unsupported hard links'); error.code = 'ENOTSUP'; throw error; };
    try { assert.throws(() => materializePinnedGzip(root, baseSpec), /unsupported/); }
    finally { fs.linkSync = originalLink; }
    assert.equal(fs.existsSync(output(root)), false);
    assert.deepEqual(fs.readdirSync(path.join(root, 'assets')), ['foreign.tmp']);
  }));
});

sources.scripts/build-bundle.mjs:
// scripts/build-bundle.mjs — production bundle for the Electron/web release (P2-18).
//
// The dev path (node server.js → browser) is ZERO-BUILD: raw ES modules + an importmap resolve
// three/rapier from vendor/. That path stays exactly as-is. This script adds a SEPARATE production
// build: esbuild bundles src/main.js + every dynamically-imported screen into a tree-shaken,
// minified output in build/web/, resolving three/rapier/addons from node_modules. The Electron
// builder ships build/web/ instead of the raw src/ tree, cutting load size substantially.
//
// Dynamic imports: src/ui/uiRoot.js imports screens through literal import() call sites,
// and src/core/* + src/render/assetLoader.js conditionally import
// rapier/three-addons. esbuild code-splits these into separate chunks automatically (each dynamic
// import becomes its own file loaded on demand).
import * as esbuild from 'esbuild';
import { materializeHundredHandRuntimeAsset } from './lib/materializeHundredHandRuntimeAsset.mjs';
import { spawn } from 'node:child_process';
import { readFile, writeFile, mkdir, readdir, stat, rm } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  acquireReleaseBuildLock,
  assertReleasePathSafe,
  copyReleaseRuntimeTrees,
  renameReleasePathWithRetry,
  validateReleaseBuildReceipt,
  writeReleaseBuildReceipt,
} from './lib/releasePackaging.mjs';
import { retailBundleAliases } from './lib/retailBundleAliases.mjs';
import { pinVercelReleaseHtml, vercelReleaseBase } from './lib/vercelReleaseBase.mjs';
import { buildRetailRuntimeWorkers, moduleWorkerEntryPoints, validateRetailModuleWorkers, RETAIL_BROWSER_TARGETS } from './lib/retailRuntimeWorkers.mjs';

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const SRC = join(ROOT, 'src');
// ZERO_TO_HERO Phase 5.1: `node scripts/build-bundle.mjs --demo` (or SPACEFACE_DEMO=1) bakes the
// demo flag into the bundle; everything demo-only folds away in an ordinary build.
const DEMO = process.argv.includes('--demo') || process.env.SPACEFACE_DEMO === '1';
// Build outside the final tree, validate it completely, then swap it into build/web. Electron
// Builder globs only build/web, so an interrupted build cannot package a partial candidate.
const FINAL_OUT = join(ROOT, 'build', 'web');
const OUT = join(ROOT, 'build', 'web.__building');
const PREVIOUS_OUT = join(ROOT, 'build', 'web.__previous');

// Count screen modules for the build log. They are imported from uiRoot.js through literal dynamic
// import call sites, so main.js is the only entry point; adding screens here as independent entries
// would duplicate shared chunks.
async function screenEntries() {
  const dir = join(SRC, 'ui', 'screens');
  const files = await readdir(dir);
  return files.filter((f) => f.endsWith('.js')).map((f) => join(dir, f));
}

// Total size of a directory tree.
async function dirSize(dir) {
  let total = 0;
  if (!existsSync(dir)) return 0;
  const entries = await readdir(dir, { withFileTypes: true });
  for (const e of entries) {
    const s = join(dir, e.name);
    if (e.isDirectory()) total += await dirSize(s);
    else total += (await stat(s)).size;
  }
  return total;
}

// Total size of only the JS files in a directory tree. JS compression/tree-shaking and the
// separately receipted render-package source projection are reported as independent savings.
async function jsSize(dir) {
  let total = 0;
  if (!existsSync(dir)) return 0;
  const entries = await readdir(dir, { withFileTypes: true });
  for (const e of entries) {
    const s = join(dir, e.name);
    if (e.isDirectory()) total += await jsSize(s);
    else if (/\.(m?js)$/i.test(e.name)) total += (await stat(s)).size;
  }
  return total;
}

async function build() {
  materializeHundredHandRuntimeAsset(ROOT);
  const releaseBase = vercelReleaseBase(process.env.VERCEL_URL);
  await recoverPublishedOutput();
  const screens = await screenEntries();
  // bootEntry is the bundled entry: it paints the boot instrument, then imports the game graph.
  // loadingTerminalArt and introSignalRemixBoot stay stable-named entry chunks so the dynamic
  // imports inside bootEntry resolve to the same names in dev and retail.
  const entryPoints = { main: join(SRC, 'ui/bootEntry.js'), 'ui/loadingTerminalArt': join(SRC, 'ui/loadingTerminalArt.js'),
    'ui/introSignalRemixBoot': join(SRC, 'ui/introSignalRemixBoot.js'),
    // Module Workers join the main build as entries so code splitting dedupes
    // their vendored deps into shared chunks instead of re-bundling them
    // (~14 MB on the sim lane). Classic workers stay separate below.
    ...moduleWorkerEntryPoints(ROOT) };

  console.log('[bundle] entry points:', Object.keys(entryPoints).length, '(bootEntry -> game + loadingTerminalArt + intro remix optics; ' + screens.length + ' screens via dynamic imports)');
  await cleanOutputDir();

  const result = await esbuild.build({
    entryPoints,
    bundle: true,
    format: 'esm',
    splitting: true,          // code-split dynamic imports into separate chunks
    outdir: OUT,
    minify: true,             // minify JS
    treeShaking: true,
    dropLabels: ['SF_DEBUG_ONLY'], // raw source keeps dev tools; production removes the statements
    sourcemap: false,         // ship without sourcemaps (smaller; dev uses raw modules)
    target: [...RETAIL_BROWSER_TARGETS], // Include Safari rather than assuming Chromium syntax
    platform: 'browser',
    // Resolve bare specifiers to the npm packages (three/rapier ship ESM in node_modules).
    // The vendor/ copies are otherwise only for the zero-build dev path; the bundle uses node_modules...
    mainFields: ['browser', 'module', 'main'],
    conditions: ['browser', 'import'],
    // ...except the vendor-patched modules the dev importmap already loads (GLTFLoader), so dev and
    // retail parse render packages with the same code.
    alias: retailBundleAliases(ROOT),
    logLevel: 'info',
    // Treat dynamic imports of literal strings as code-splittable chunks (default).
    legalComments: 'none',
    define: {
      // Define the browser-facing process object too: guards test `typeof process` first.
      process: JSON.stringify({ env: { NODE_ENV: 'production' }, versions: {}, argv: [] }),
      __SPACEFACE_PRODUCTION__: 'true',
      // Main and module-worker entries share this build, so every worker/chunk chain
      // follows the same immutable release while the page keeps its canonical origin.
      __SPACEFACE_RELEASE_BASE__: JSON.stringify(releaseBase),
      __SPACEFACE_DEMO__: DEMO ? 'true' : 'false',
    },
  });

  // Copy every URL-fetched runtime root from one canonical map. Ship authoring sources, Blender
  // files, evidence, rejected candidates, and previous exports are intentionally excluded: normal
  // play is release-authored and reads only assets/ships/release/. This preserves visual quality
  // byte-for-byte while preventing gigabytes of non-runtime production files from entering retail.
  await mkdir(OUT, { recursive: true });
  await copyReleaseRuntimeTrees({ root: ROOT, webRoot: OUT });
  await runNodeGate('scripts/check-render-package-instance-plan.mjs', [
    '--package-dir', join(OUT, 'assets', 'ships', 'release', 'render-packages'),
  ]);

  // URL-created workers are separate programs, not dependencies of the main bundle.
  // Classic workers emit here; module workers already emitted inside the main
  // build — validate their import graph resolves inside the deployment root.
  await buildRetailRuntimeWorkers({ esbuild, root: ROOT, outdir: OUT });
  await validateRetailModuleWorkers({ outdir: OUT });

  // Write a bundled index.html (no importmap — the bundle resolves everything).
  const bundledHtml = await buildBundledHtml();
  await writeFile(join(OUT, 'index.html'), bundledHtml, 'utf8');

  // Deterministic, hash-bound receipt: no timestamps, sorted file records, exact declared
  // projection parity for every copied runtime root. Identical inputs reproduce the same digest.
  const releaseReceipt = await writeReleaseBuildReceipt({
    root: ROOT,
    webRoot: OUT,
  });

  // Report JS savings independently from the receipt's render-package source projection. Raw JS =
  // src/ + vendor/three+rapier+addons; bundled JS is minified, tree-shaken, and code-split. Asset
  // byte savings are recorded separately because they remove only package-covered source GLBs.
  const rawJsSize = (await jsSize(SRC)) + (await jsSize(join(ROOT, 'vendor')));
  const outJsSize = await jsSize(OUT);
  const saving = rawJsSize > 0 ? ((1 - outJsSize / rawJsSize) * 100) : 0;
  console.log('[bundle] raw JS (src + vendor/three+rapier): ' + (rawJsSize / 1024 / 1024).toFixed(2) + ' MB');
  console.log('[bundle] bundled JS (minified + tree-shaken): ' + (outJsSize / 1024 / 1024).toFixed(2) + ' MB (' +
    saving.toFixed(0) + '% smaller)');

  if (result.errors.length) throw new Error(`[bundle] esbuild returned ${result.errors.length} errors`);
  if (result.warnings.length) console.warn('[bundle] warnings:', result.warnings.length);
  // Re-read every staged byte at the final publication boundary. Nothing asynchronous may inspect
  // or transform OUT after this point; a mismatched source/output generation never reaches the
  // atomic rename into build/web.
  const releaseValidation = await validateReleaseBuildReceipt({
    root: ROOT,
    webRoot: OUT,
    receipt: releaseReceipt,
  });
  if (!releaseValidation.pass) {
    throw new Error(`[bundle] invalid release receipt: ${releaseValidation.failures.join('; ')}`);
  }
  console.log(`[bundle] receipt ${releaseReceipt.output.digest} (${releaseReceipt.output.fileCount} files)`);
  await publishOutputDir();
  console.log('[bundle] OK → build/web/');
  return { outJsSize, rawJsSize };
}

async function runNodeGate(relativeScript, args = []) {
  const script = resolve(ROOT, ...relativeScript.split('/'));
  await new Promise((resolveGate, rejectGate) => {
    const child = spawn(process.execPath, [script, ...args], { cwd: ROOT, stdio: 'inherit' });
    child.once('error', rejectGate);
    child.once('exit', (code, signal) => {
      if (code === 0) resolveGate();
      else rejectGate(new Error(
        `[bundle] prerequisite ${relativeScript} failed (${signal ? `signal ${signal}` : `exit ${code}`})`,
      ));
    });
  });
}

async function recoverPublishedOutput() {
  await assertReleasePathSafe({ root: ROOT, path: FINAL_OUT, label: 'release output', allowMissing: true });
  await assertReleasePathSafe({ root: ROOT, path: PREVIOUS_OUT, label: 'release backup', allowMissing: true });
  if (!existsSync(FINAL_OUT) && existsSync(PREVIOUS_OUT)) await renameReleasePathWithRetry(PREVIOUS_OUT, FINAL_OUT);
  if (existsSync(FINAL_OUT) && existsSync(PREVIOUS_OUT)) {
    await rm(PREVIOUS_OUT, { recursive: true, force: true });
  }
}

async function cleanOutputDir() {
  const expected = resolve(ROOT, 'build', 'web.__building');
  const actual = resolve(OUT);
  if (actual !== expected) throw new Error(`[bundle] refused to clean unexpected output dir: ${actual}`);
  await assertReleasePathSafe({ root: ROOT, path: actual, label: 'release staging output', allowMissing: true });
  await rm(actual, { recursive: true, force: true });
  await mkdir(actual, { recursive: true });
}

async function publishOutputDir() {
  const expectedFinal = resolve(ROOT, 'build', 'web');
  const expectedStaging = resolve(ROOT, 'build', 'web.__building');
  const expectedPrevious = resolve(ROOT, 'build', 'web.__previous');
  if (resolve(FINAL_OUT) !== expectedFinal || resolve(OUT) !== expectedStaging
    || resolve(PREVIOUS_OUT) !== expectedPrevious) {
    throw new Error('[bundle] refused to publish unexpected output directories');
  }

  // Recover a prior interrupted swap before beginning a new one. The old validated tree remains
  // authoritative until the new staging tree has been fully built and receipt-validated.
  await recoverPublishedOutput();

  let previousMoved = false;
  try {
    if (existsSync(FINAL_OUT)) {
      await renameReleasePathWithRetry(FINAL_OUT, PREVIOUS_OUT);
      previousMoved = true;
    }
    await renameReleasePathWithRetry(OUT, FINAL_OUT);
  } catch (error) {
    if (previousMoved && !existsSync(FINAL_OUT) && existsSync(PREVIOUS_OUT)) {
      try { await renameReleasePathWithRetry(PREVIOUS_OUT, FINAL_OUT); }
      catch (restoreError) {
        throw new AggregateError([error, restoreError], '[bundle] publish failed and prior output restoration failed');
      }
    }
    throw error;
  }
  if (existsSync(PREVIOUS_OUT)) await rm(PREVIOUS_OUT, { recursive: true, force: true });
}

// Build the production index.html: same DOM shell as the dev index.html, but loads the bundled
// main.js (no importmap — the bundle inlines three/rapier) and the copied CSS.
async function buildBundledHtml() {
  const devHtml = await readFile(join(ROOT, 'index.html'), 'utf8');
  // The dev html has an importmap script + a module script pointing at ./src/main.js. Replace both
  // with a single module script pointing at the bundled ./main.js (esbuild names it after the first
  // entry point). Keep the CSS links, the DOM shell, the meta, the icon.
  const html = devHtml
    // strip the importmap block (the bundle resolves bare specifiers itself), including the
    // dev-only comment that explains it — check-bundle fails on any 'importmap' text left behind
    .replace(/(<!--[^>]*importmap[^>]*-->\s*)?<script type="importmap">[\s\S]*?<\/script>\s*/, '')
    // dev warmup links resolve through the importmap and have no meaning in the bundle:
    // the bundled main.js covers src/, and the vendor/ tree it points at is not shipped.
    .replace(/<link rel="modulepreload"[^>]*>\s*/g, '')
    // src/-scoped preload/prefetch hints are equally dev-only — the bundle does
    // not ship the src/ tree they point at.
    .replace(/<link\b(?=[^>]*\brel=["'](?:preload|prefetch)["'])(?=[^>]*\bhref=["']\.\/src\/)[^>]*>\s*/gi, '')
    // point the module script at the bundled output
    .replace('<script type="module" src="./src/ui/bootEntry.js"></script>', '<script type="module" src="./main.js"></script>');
  // A drifted index.html must fail the build here — a silently missed rewrite ships a
  // bundle whose script tag still points at the raw src/ tree and 404s at packaged boot.
  // Assert the rewrites actually landed (not just that no leftovers survive): if the
  // entry tag drifts so the pattern no longer matches, the replace no-ops and only
  // the presence check below can catch it.
  if (!html.includes('<script type="module" src="./main.js"></script>')) {
    throw new Error('index.html rewrite produced no bundled entry reference; update buildBundledHtml');
  }
  if (/["'(]\s*\.\/src\//.test(html) || /from\s+['"]\.\/src\//.test(html)) {
    throw new Error('index.html rewrite missed a source-module reference; update buildBundledHtml');
  }
  return pinVercelReleaseHtml(html, process.env.VERCEL_URL);
}

async function runLockedBuild() {
  const lock = await acquireReleaseBuildLock({ projectRoot: ROOT, buildRoot: join(ROOT, 'build') });
  let result = null;
  let failure = null;
  try {
    result = await build();
  } catch (error) {
    failure = error;
    try {
      await assertReleasePathSafe({ root: ROOT, path: OUT, label: 'release staging output', allowMissing: true });
      await rm(OUT, { recursive: true, force: true });
    }
    catch (cleanupError) {
      failure = new AggregateError([error, cleanupError], '[bundle] build failed and staging cleanup failed');
    }
  }
  try {
    await lock.release();
  } catch (releaseError) {
    failure = failure
      ? new AggregateError([failure, releaseError], '[bundle] build failed and its lock could not be released')
      : releaseError;
  }
  if (failure) throw failure;
  return result;
}

runLockedBuild().catch((err) => {
  console.error('[bundle] FAILED:', err);
  process.exit(1);
});

